entries[143326] = { ["name"] = "Stein von Jordan", ["text"] = "Wird an Kriegsmeute gebunden" }
entries[143327] = { ["name"] = "Kuhhufgerechte Lochaberaxt", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n8 - 16 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
