entries[143478] = { ["name"] = "Arenaeinladung", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine sorgfältig mit dem Blut der Gefallenen verfasste Notiz.\"" }
entries[143479] = { ["name"] = "Ausgefranstes Banner", ["text"] = "Wird beim Aufheben gebunden\n\"Blutverschmiert und zerrissen, doch das macht es nur noch prächtiger.\"\nVerkaufspreis:" }
entries[143486] = { ["name"] = "Barriere des Arkusformers", ["text"] = "Wird beim Aufheben gebunden\n\"Der Arkusformer gab sich bei dem Kristall viel Mühe. Die Macht kann unterdrückt werden, aber selbst dann ist sie noch stark.\"\nVerkaufspreis:" }
entries[143487] = { ["name"] = "Verzauberte Dämmerlilie", ["text"] = "Wird beim Aufheben gebunden\n\"Gelegentlich findet man Dämmerlilien von großer Macht. Vermutlich ist das auch der Grund, warum sie zu einem so bedeutenden Symbol geworden sind.\"\nVerkaufspreis:" }
entries[143488] = { ["name"] = "Verzauberte Nachtgeborenenmünze", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Münze wurde seit Generationen weitergegeben und enthält nachklingendes Wissen seiner ehemaligen Besitzer.\"\nVerkaufspreis:" }
entries[143489] = { ["name"] = "Totem des wütenden Sturms", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen wütenden Sturm des Scharfsehers beschwört.\nBeschwört Euren wütenden Sturm des Scharfsehers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Windzorn. Überladung: (2).\"\nQuest:\nZorn der Stürme" }
entries[143490] = { ["name"] = "Blutige Zügel des düsteren Vorboten", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein blutrotes Omen der Schattenklinge beschwört.\nBeschwört Euer blutrotes Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Auf ihm sieht man das Blut Eurer Feinde gar nicht erst.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran" }
entries[143491] = { ["name"] = "Verpestete Zügel des düsteren Vorboten", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein unheilvolles Omen der Schattenklinge beschwört.\nBeschwört Euer unheilvolles Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Für die giftig Veranlagten.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran" }
entries[143492] = { ["name"] = "Nachtschwarze Zügel des düsteren Vorboten", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein tödliches Omen der Schattenklinge beschwört.\nBeschwört Euer tödliches Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Euch wird niemand kommen hören.\"\nVerkäufer:\nZan Messerritzel\nZone:\nDalaran" }
entries[143493] = { ["name"] = "Klingengesäumte Zügel des düsteren Vorboten", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein mörderisches Omen der Schattenklinge beschwört.\nBeschwört Euer mörderisches Omen der Schattenklinge oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das ideale Fortbewegungsmittel für Meuchelmörder, da es beim Fliegen geräuschlos bleibt. Nützlich, wenn man sich anschleichen möchte.\"\nQuest:\nVor aller Augen verborgen" }
entries[143494] = { ["name"] = "Eine geheimnisvolle Notiz", ["text"] = "Questgegenstand\n\"Stammt anscheinend von einem der Kultisten, von denen Karam sprach.\"\n<Zum Lesen rechtsklicken>" }
entries[143495] = { ["name"] = "Zauberstab des Inquisitors", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n1 Schattenschaden Geschwindigkeit 2.00\n(0.5 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[143496] = { ["name"] = "Manifest des Netherpakts", ["text"] = "Questgegenstand\n\"Diese Schriften legen die Ziele des Netherpakts im Detail dar.\"\n<Zum Lesen rechtsklicken>" }
entries[143497] = { ["name"] = "Geläutertes Dämonenblut", ["text"] = "Questgegenstand" }
entries[143498] = { ["name"] = "Finger des aufgeladenen Konstrukts", ["text"] = "Wird beim Aufheben gebunden\n\"Die Magistrix wird langsam leichtsinnig. Schon der kleine Finger dieses Dings verfügt über genug Macht, um den halben Palast einzureißen.\"\nVerkaufspreis:" }
entries[143499] = { ["name"] = "Überladene Maske des Infiltrators", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Maske wurde unter Zeitdruck gefertigt und mit zu viel Macht erfüllt. Sie ist kurz davor zu platzen.\"\nVerkaufspreis:" }
entries[143501] = { ["name"] = "Sonnenlilie", ["text"] = "Questgegenstand\n\"Eine aromatische Blume, die in Suramar beheimatet ist.\"" }
entries[143502] = { ["name"] = "Schimmernde Zügel des goldenen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein goldenes Streitross des Hochlords beschwört.\nBeschwört Euer goldenes Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das vornehmste aller Rösser.\"\nQuest:\nSuche in den Schatten" }
entries[143503] = { ["name"] = "Strenge Zügel des rachsüchtigen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein rachsüchtiges Streitross des Hochlords beschwört.\nBeschwört Euer rachsüchtiges Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es ist unklar, warum genau es so auf Rache aus ist.\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts" }
entries[143504] = { ["name"] = "Stoische Zügel des wachsamen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein wachsames Streitross des Hochlords beschwört.\nBeschwört Euer wachsames Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der ausdruckslose Blick dieses Rosses ist in Wahrheit ein Zeichen von \"Wachsamkeit\".\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts" }
entries[143505] = { ["name"] = "Heraldische Zügel des tapferen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein tapferes Streitross des Hochlords beschwört.\nBeschwört Euer tapferes Streitross des Hochlords oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Verfügt über viele Punkte, die für seine Tapferkeit sprechen.\"\nVerkäufer:\nKreuzfahrerlord Dalfors\nZone:\nDas Sanktum des Lichts" }
