entries[143533] = { ["name"] = "Machterfüllter Grubenlordhauer", ["text"] = "Wird beim Aufheben gebunden\n\"Rozzeleth war schon immer ein mächtiger Dämon, doch während seiner Stationierung in Suramar hat er wohl viel uraltes Mana aufgenommen. Nach der Trennung von seinem dämonischen Körper summt der Hauer noch immer.\"\nVerkaufspreis:" }
entries[143534] = { ["name"] = "Zauberstab des simulierten Lebens", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Fokussiert Arkanmagie, um ein lebendes Konstrukt zu erschaffen. Es ist unbekannt, was für Formen dieses annehmen kann.\n\"Von Magus Willem West hergestellt.\"" }
entries[143535] = { ["name"] = "Teufelssteinanhänger", ["text"] = "Questgegenstand\n\"Der eingesetzte Edelstein glüht vor Teufelsenergie.\"" }
entries[143536] = { ["name"] = "Überladene Seherkugel", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[143537] = { ["name"] = "Manafokus", ["text"] = "Questgegenstand\nEinzigartig\n\"Während das Licht diesen Gegenstand durchdringt, wird es auf merkwürdige Art und Weise gebrochen und verzerrt.\"" }
entries[143538] = { ["name"] = "Umschlungene telemantische Kugel", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält gleichzeitig alle möglichen Telemantieergebnisse. Theoretisch könnte es Euch an jeden beliebigen Ort bringen. Tatsächlich schien es jedoch nur dem Ruf der Natur zu folgen.\"\nVerkaufspreis:" }
entries[143539] = { ["name"] = "Versteckter Gürtel", ["text"] = "Kosmetisch\nTaille Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[143540] = { ["name"] = "Fehlkonfigurierter Abstimmungskristall", ["text"] = "Wird beim Aufheben gebunden\n\"Lasst Euch nicht täuschen, auch wenn es nicht den Leylinienmanipulator ausschalten konnte, ist es äußerst mächtig.\"\nVerkaufspreis:" }
entries[143542] = { ["name"] = "Allheilmittelchen der Firma Krone", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: \"Heilt\" alle Gifte, Krankheiten, Flüche, Verhexungen, Geister, Verzauberungen, magischen Effekte und Kahlköpfigkeit. (1 Min Abklingzeit)\n\"Dieser Trank wurde nicht vom Amt für Alchemie zugelassen. Durch Einnahme dieses Tranks übernimmt der Trinker jegliche Verantwortung für dessen Auswirkungen.\"\nVerkaufspreis:" }
entries[143543] = { ["name"] = "Zwölfsaitige Gitarre", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schlägt die Saiten ein paar Mal an und spielt eine unheimliche und unvergessliche Melodie. (1 Stunde, 6 Min Abklingzeit)" }
entries[143544] = { ["name"] = "Schädel der Verderbnis", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Dämonenjäger\nBenutzen: Sinnt über die Macht nach, die aus dem dämonischen Schädel dringt. (30 Sek. Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\"Nicht alle Magie eines Dämons kehrt in den Wirbelnden Nether zurück.\"" }
entries[143545] = { ["name"] = "Teufelsfokussierkristall", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Dämonenjäger\nBenutzen: Sinnt über die Macht des Teufelskristalls nach. (30 Sek. Abklingzeit)\n\"Es wurde vom Strahl eines großen Beobachterdämons graviert und kann unglaubliche Teufelsenergie aussenden.\"" }
entries[143548] = { ["name"] = "Teufelssehnentasche", ["text"] = "Questgegenstand\n\"Die Tasche ist aus Sehnen und Fasern einer Teufelsbestie geschnürt und stinkt geradezu nach Teufelsenergie.\"" }
entries[143549] = { ["name"] = "Leere Motivationskristallkiste", ["text"] = "Questgegenstand" }
entries[143550] = { ["name"] = "Kiste mit \"neuen\" Hufeisen", ["text"] = "Questgegenstand" }
entries[143551] = { ["name"] = "Rosenbouquet", ["text"] = "Questgegenstand\n\"Die vermisst niemand, ihr letztes Stück war eh die reinste Hinrichtung.\"" }
entries[143552] = { ["name"] = "Positive Kritik", ["text"] = "Questgegenstand\n\"Vor dem Untergang der beiden Helden entwickelte sich fast eine ergreifende Darstellung.\"" }
entries[143553] = { ["name"] = "Negative Kritik", ["text"] = "\"Kein Wunder, dass es Julianne auf solch eine erbärmliche Bühne getrieben hat. Sie sollte sich selbst einen Schluck Gift gönnen.\"\nVerkaufspreis:" }
entries[143554] = { ["name"] = "Negative Kritik", ["text"] = "\"Romulo und Julianne wurden aus gutem Grund auf die wechselnde Bühne verbannt. Bei ihnen kann man sich nur über den aufführungsfreien Abend freuen.\"\nVerkaufspreis:" }
entries[143555] = { ["name"] = "Rotkäppchens rotes Käppchen", ["text"] = "Questgegenstand" }
entries[143556] = { ["name"] = "Verkohlte Knochenfragmente", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Knochen qualmen noch und sollten man sollte vorsichtig mit ihnen umgehen.\"" }
entries[143558] = { ["name"] = "Versorgungskiste des Hochbergs", ["text"] = "Questgegenstand\n\"Dieser Vorrat enthält verschiedene Ressourcen aus der Wildnis des Hochbergs.\"" }
entries[143559] = { ["name"] = "Wyrmzungentruhenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet eine Wyrmzungenschatztruhe." }
entries[143560] = { ["name"] = "Schwingende Teufelsenergie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Durchdringt eine ungebundene zeitlose Rüstungsmarke mit großer Macht und erschafft so einen Gegenstand, der Eurer Beutespezialisierung entspricht.\n\"Kann in Teufelssplitter zerlegt werden.\"" }
entries[143561] = { ["name"] = "Abgebrannte Schattenkerze", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Zum Ausleuchten finsterer Orte nicht besonders nützlich, dient aber als Siegesbeweis für Euren Champion.\"" }
