entries[143615] = { ["name"] = "Technik: Glyphe 'Knisternder Ochsenblitz'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Knisternder Ochsenblitz' herstellt.\nStellt eine Glyphe 'Knisternder Ochsenblitz' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Knisternder Ochsenblitz'\nKlassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Schwarzen Ochsen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)" }
entries[143616] = { ["name"] = "Technik: Glyphe 'Getreues Ross'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Getreues Ross' herstellt.\nStellt eine Glyphe 'Getreues Ross' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Getreues Ross'\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Volksreittier wird durch ein 'Göttliches Ross' ersetzt. Exklusiv mit: Zaumzeug des tapferen Streitrosses Zaumzeug des rachsüchtigen Streitrosses Zaumzeug des wachsamen Streitrosses Zaumzeug des goldenen Streitrosses\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)" }
