entries[143631] = { ["name"] = "Urzeitlicher Flammensäbler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren urzeitlichen Flammensäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die urzeitliche Landschaft von Azeroth war einst voll von Elementarkreaturen aller Arten.\"\nPromotion\nHeroes of the Storm" }
entries[143633] = { ["name"] = "Meisterliche Manabrötchen", ["text"] = "Einzigartig (5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 69 Meisterschaft.\n\"Kann nur auf den Verheerten Inseln und im Szenario 'Bändigung der Scheiben' benutzt werden.\"\nVerkaufspreis:" }
entries[143634] = { ["name"] = "Kritischer Katzenwels", ["text"] = "Einzigartig (5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 69 kritischen Trefferwert.\n\"Kann nur auf den Verheerten Inseln und im Szenario 'Bändigung der Scheiben' benutzt werden.\"\nVerkaufspreis:" }
entries[143635] = { ["name"] = "Temporeicher Hummus", ["text"] = "Einzigartig (5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 69 Tempo.\n\"Kann nur auf den Verheerten Inseln und im Szenario 'Bändigung der Scheiben' benutzt werden.\"\nVerkaufspreis:" }
entries[143636] = { ["name"] = "Arkane Schiene", ["text"] = "Einzigartig (5)\nBenutzen: Heilt im Verlauf von 8 Sek. 6600 Gesundheit.\n\"Kann nur auf den Verheerten Inseln und im Szenario 'Bändigung der Scheiben' benutzt werden.\"\nVerkaufspreis:" }
entries[143637] = { ["name"] = "Höllenfeuerzügel des zänkischen Zornrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein zänkisches Zornross des Netherfürsten beschwört.\nBeschwört Euer zänkisches Zornross des Netherfürsten oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nSchließt Eure Ordenshallenkampagne ab.\n\n\"Als Besitzer sollte man sich auf hitzige Streitereien einstellen. Zumindest gelegentlich.\"\nVerkäufer:\nCalydus\nZone:\nDie Schreckensnarbe" }
entries[143638] = { ["name"] = "Mondgeküsste Feder", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man sich in die Mondschwingengestalt des Erzdruiden verwandelt.\nErmöglicht Euch, die Gestalt einer Mondschwingeneule als Reisegestalt anzunehmen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
