entries[143728] = { ["name"] = "Zeitloses Manöver", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Krieger\nAnlegen: 'Heldenhafter Sprung' erhält 2 zusätzliche Aufladungen.\n\"Stürzt Euch mit der tödlichen Ruhe einer Abrissbirne ins Getümmel.\"\nVerkaufspreis:" }
entries[143731] = { ["name"] = "Fass Sturmgebräu", ["text"] = "Questgegenstand\n\"Achtung: Trinken auf eigene Gefahr.\"" }
entries[143732] = { ["name"] = "Unstete Mahnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Kette\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Schamane\nAnlegen: Der Effekt von [ Heldentum / Kampfrausch] hält auf Euch 75% länger an.\n\"Vergesst nicht, wer der wahre Feind ist...\"\nVerkaufspreis:" }
