entries[143739] = { ["name"] = "Mal des Seelenspalters", ["text"] = "Wird beim Aufheben gebunden\n\"Aargoss war eitel und darauf erpicht, jeden von seinen Taten wissen zu lassen.\"\nVerkaufspreis:" }
entries[143740] = { ["name"] = "Verzaubertes Banner der Sin'dorei", ["text"] = "Wird beim Aufheben gebunden\n\"Mit einem mächtigen Zauberschutz gekennzeichnet. Wird von Blutelfen verwendet, um ihre Grenzen zu ziehen und Angreifer abzuschrecken.\"\nVerkaufspreis:" }
entries[143741] = { ["name"] = "Gesegnetes Banner der Kaldorei", ["text"] = "Wird beim Aufheben gebunden\n\"Von Elune gesegnet. Diese Banner werden an Frontlagern der Nachtelfen aufgestellt, um Schutz und Beistand zu gewähren.\"\nVerkaufspreis:" }
entries[143742] = { ["name"] = "Szepter von Kerxan", ["text"] = "Wird beim Aufheben gebunden\n\"Ein mächtiges Szepter, das Ingra aus einer anderen Welt mitbrachte.\"\nVerkaufspreis:" }
entries[143743] = { ["name"] = "Hochgeladener Manapfropfen", ["text"] = "Wird beim Aufheben gebunden\n\"Nachdem sie sich über Jahrtausende angestaut hat, platzt die Energie förmlich aus ihm hervor.\"\nVerkaufspreis:" }
entries[143744] = { ["name"] = "Gesegnete Klingen der Rabenkrone", ["text"] = "Wird beim Aufheben gebunden\n\"Ein paar Klingen, denen der Segen eines Priesters unglaubliche Energie verliehen hat. Unsere neuen Rekruten wären damit wohl ein wenig überfordert.\"\nVerkaufspreis:" }
entries[143745] = { ["name"] = "Fokus des Leyschöpfers", ["text"] = "Wird beim Aufheben gebunden\n\"Mächtiges Handwerk erfordert mächtige Instrumente.\"\nVerkaufspreis:" }
entries[143746] = { ["name"] = "Teufelsgeküsste Klinge", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kraftvolle Verschmelzung von Energien.\"\nVerkaufspreis:" }
entries[143747] = { ["name"] = "Schlüssel zur Nachtfestung", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Schlussel wurde über die Jahrtausende zu weit mehr als nur einem Schlüssel. Nehmt ihn! Benutzt ihn, um Macht freizusetzen, statt sie anderen zu verschließen.\"\nVerkaufspreis:" }
entries[143748] = { ["name"] = "Leyschuppenkoi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewinnt 25 uraltes Mana.\nBenötigt den Ruf 'Guter Freund' bei Sha'leth." }
entries[143749] = { ["name"] = "Verderbte Matrix der Nachtgeborenen", ["text"] = "Wird beim Aufheben gebunden\n\"Der aufwendige Talisman der Nachtgeborenen wurde verderbt und für schändliche Taten missbraucht. Es wäre besser, ihm seine Macht zu entziehen und sie für einen edleren Zweck zu nutzen.\"\nVerkaufspreis:" }
entries[143750] = { ["name"] = "Glyphe 'Zwielichtwachstum'", ["text"] = "Klassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt Euer 'Blühendes Leben' zu einer üppigen Zwielichtblume aufblühen.\nVerkaufspreis:" }
entries[143751] = { ["name"] = "Technik: Glyphe 'Zwielichtwachstum'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Zwielichtwachstum' herstellt.\nStellt eine Glyphe 'Zwielichtwachstum' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Zwielichtwachstum'\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt Euer 'Blühendes Leben' zu einer üppigen Zwielichtblume aufblühen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)" }
entries[143753] = { ["name"] = "Durchnässter Haustierbedarf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet den Beutel.\n\"Enthält gewöhnlich ein paar Kampfhaustierbandagen und Haustierglücksbringer. Aber von Zeit zu Zeit kann man darin auch ein spezielles Haustier finden.\"" }
entries[143754] = { ["name"] = "Höhlenmokassinschlange", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick eine Höhlenmokassinschlange beschwören oder wieder freigeben.\n80 ( 80)" }
entries[143755] = { ["name"] = "Junger Giftzahn", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick einen jungen Giftzahn beschwören oder wieder freigeben.\n80 ( 80)" }
entries[143756] = { ["name"] = "Ewiglebende Spore", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick eine ewiglebende Spore beschwören oder wieder freigeben.\n80 ( 80)" }
entries[143757] = { ["name"] = "Kopfstück des Schattenrats", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Symbol des Schattenrats bildet das Kopfstück von Gul'dans Stab. Es hat eine tiefe Verbindung zu den Schattenlanden und wurde so zu einem mächtigen Instrument in den Händen Gul'dans und seiner Legionsherren.\"\nVerkaufspreis:" }
entries[143758] = { ["name"] = "Gutschein für Freigetränke", ["text"] = "Wird beim Aufheben gebunden\n\"Bei Barkeeperin Townsley in Bizmos Boxbar abliefern, um 2 Minuten lang alle Spieler mit Freigetränken zu versorgen!\"\nVerkaufspreis:" }
entries[143759] = { ["name"] = "Mietformular für VIP-Räume", ["text"] = "Wird beim Aufheben gebunden\n\"Bei einem Türsteher der VIP-Lounge in Bizmos Boxbar abgeben, um 10 Minuten lang allen Spielern VIP-Zugang zu gewähren!\"\nVerkaufspreis:" }
entries[143760] = { ["name"] = "Trankspender der Kampfgilde", ["text"] = "Wird beim Aufheben gebunden\n\"Bei Quackenbusch oder Dershway in Bizmos Boxbar abliefern, um ein Fass zu kaufen, das alle Spieler 30 Minuten lang mit kostenlosen Tränken versorgt.\"\nVerkaufspreis:" }
entries[143761] = { ["name"] = "Blutgetränkte Engelsfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Bei Lidiya Peyton in Bizmos Boxbar abliefern, um 30 Minuten lang einen Friedhof in der Kampfgilde zu mieten.\"\nVerkaufspreis:" }
